338	func removeEntireHooks(groups []MatcherGroup) []MatcherGroup {
339		result := make([]MatcherGroup, 0, len(groups))
340		for _, group := range groups {
341			filtered := make([]HookEntry, 0, len(group.Hooks))
342			for _, hook := range group.Hooks {
343				if !isEntireHook(hook.Command) {
344					filtered = append(filtered, hook)
