func TestOwnerExited_EndedAtSetIsFalse(t *testing.T) {
	t.Parallel()
	// EndedAt is the other half of "already finalized" — the rest of the CLI
	// filters on it alongside PhaseEnded, so OwnerExited must agree or a
	// finalized session could be swept a second time.
	deadOwner := &proclive.Identity{PID: 999999999, Start: "never"}
	ended := time.Now()
	s := &State{Phase: PhaseIdle, Owner: deadOwner, EndedAt: &ended}
	if s.OwnerExited() {
		t.Error("OwnerExited(EndedAt set) = true, want false")
	}
}

func TestOwnerExited_IdlePhaseWithDeadOwnerIsTrue(t *testing.T) {
	t.Parallel()
	// The Codex shape: the agent finished its last turn (ACTIVE -> IDLE) and
	// then quit without a session-end hook. The session must still be
	// reclaimable, or it lingers as "active" until it is hard-deleted.
	deadOwner := &proclive.Identity{PID: 999999999, Start: "never"}
	s := &State{Phase: PhaseIdle, Owner: deadOwner}
	if !s.OwnerExited() {
		t.Error("OwnerExited(phase=idle, dead owner) = false, want true")
	}
}

