func HookTrustGaps(repoRoot string) []string {
	hooksJSONPath := filepath.Join(repoRoot, ".codex", "hooks.json")
	declared, ok := declaredCodexEvents(hooksJSONPath)
	if !ok || len(declared) == 0 {
